UPDATE mes_operation_status SET status = 'ready' WHERE wo_number = ? AND status = 'pending' AND operation_id IN (SELECT e.successor_op FROM mes_operation_edge e WHERE e.predecessor_op = ? AND NOT EXISTS (SELECT 1 FROM mes_operation_edge pe LEFT JOIN mes_operation_status ps ON ps.wo_number = ? AND ps.operation_id = pe.predecessor_op WHERE pe.routing_id = e.routing_id AND pe.successor_op = e.successor_op AND (ps.status IS NULL OR ps.status <> 'complete')))
